"""--- GoalWrite a Python program that prints the relative frequence of each letterof the alphabet (without distinguishing between lower and upper case) in thebook.--- Specifications- the program should have a --help option summarizing the usage- the program should accept the path to the input file from the command line- the program should print out the total elapsed time- the program should have an option to display a histogram of the frequences- [optional] the program should have an option to skip the parts of the text  that do not pertain to the book (e.g., preamble and license)- [optional] the program should have an option to print out the basic book  stats (e.g., number of characters, number of words, number of lines, etc.)"""import argparsefrom matplotlib import pyplot as pltfrom numpy import zerosfrom time import perf_counter# Help optionparser = argparse.ArgumentParser(    description="Script to count frequence of a letter "    "and show an histogram of it")parser.add_argument(    "--file",    type=str,    default="The republic by Plato.txt",    help="File path to analayze (Default: 'The republic by Plato.txt')",)# Read commands in the terminalargs = parser.parse_args()start_time = perf_counter()# Read filetry:    with open(args.file, "r", encoding="utf-8") as file:        book = file.read()except FileNotFoundError:    print(f"Error: File '{args.file}' doesn't exist")    exit(1)def letter_counter(lowercase_letter, uppercase_letter):    counter = 0    for character in book:        if character == lowercase_letter or character == uppercase_letter:            counter += 1    return counterdef print_counter(lowercase_letter, uppercase_letter):    print(        f"Letter {lowercase_letter} appears "        f"{letter_counter(lowercase_letter, uppercase_letter)} times"    )lowercase_string = "abcdefghijklmnopqrstuvwxyz"array_counter = zeros(26, dtype=int)i = 0for letter in lowercase_string:    print_counter(letter, letter.upper())    number_letter = letter_counter(letter, letter.upper())    array_counter[i] = number_letter    i += 1# Histogramplt.title("Histogram of letters frequency")plt.bar(list(lowercase_string), array_counter)plt.show()# Elapsed timeend_time = perf_counter()elapsed_time = end_time - start_timeprint(f"Elapsed time is {elapsed_time:.3f} seconds")